"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1106],{20196:e=>{e.exports=JSON.parse('{"functions":[{"name":"setBrightness","desc":"Returns `color` with its HSV value reduced by `amount`, clamped to 0-1.\\n\\n:::caution The amount is subtracted\\nDespite the name, this *darkens* by `amount` rather than setting brightness to\\nit. Pass a negative amount to brighten.\\n:::\\n\\n```lua\\nlocal pressed = Colors.setBrightness(theme.accent, 0.15) -- darker\\nlocal hover = Colors.setBrightness(theme.accent, -0.1) -- lighter\\n```","params":[{"name":"color","desc":"Base color","lua_type":"Color3"},{"name":"amount","desc":"How much to subtract from the value channel","lua_type":"number"}],"returns":[{"desc":"","lua_type":"Color3"}],"function_type":"static","source":{"line":33,"path":"src/Shared/Class/Colors.luau"}},{"name":"setSaturation","desc":"Returns `color` with its HSV saturation reduced by `amount`, clamped to 0-1.\\n\\nSubtracts rather than sets, the same way [Colors.setBrightness] does \u2014 a positive\\namount washes the color out, a negative one deepens it.","params":[{"name":"color","desc":"Base color","lua_type":"Color3"},{"name":"amount","desc":"How much to subtract from the saturation channel","lua_type":"number"}],"returns":[{"desc":"","lua_type":"Color3"}],"function_type":"static","source":{"line":52,"path":"src/Shared/Class/Colors.luau"}}],"properties":[],"types":[],"name":"Colors","desc":"Small HSV adjustments on a [Color3], for deriving hover/pressed/disabled variants\\nof a base color instead of hand-picking each one.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":10,"path":"src/Shared/Class/Colors.luau"}}')}}]);